let S={clients:{},connections:{},job:{}}, R={uploads:[],runs:[],activity:[]}, current='dashboard', page=0, videoPage=0, recentPage=0, selected=new Set(), busy=false, lastJob='', pendingResult=null;
let filters={search:'',status:'',github:'',source:'',tag:''}, videoFilters={search:'',status:'',client:''}, recentFilters={search:'',client:'',mode:'all'}, modalData={}, chartPeriod=7, recordDay='';
const pages=[['dashboard','Dashboard','▦'],['channels','Channels','▤'],['videos','Videos','▷'],['recent','Recent posts','◷'],['youtube','YouTube','▶'],['drive','Google Drive','△'],['telegram','Telegram','➤'],['automation','Automation','⚡'],['matching','Folder matching','⇄'],['server','Server','▣'],['backup','Backup','↥'],['help','Help','?']];
const titles={matching:['Folder → channel matching','Same name suggests a route. Exact ID verification and confirmation protect every upload.'],server:['Server','Cloud workers, backup health and your account security.'],dashboard:['Dashboard','Your channels and latest uploads.'],recent:['Recent posts','Latest uploads, newest first.'],channels:['Channels','Your sources, exact destinations and posting status in one place.'],videos:['Videos','Requested visibility and verified visibility are shown separately.'],youtube:['YouTube','Your Google API app and every authorized YouTube channel.'],drive:['Google Drive','One main folder. Every client sub-folder uses the same authorization.'],telegram:['Telegram','Your bot. Upload notices, alerts, summaries and commands.'],automation:['Automation','Health checks, protection, quotas and a clear activity history.'],backup:['Backup','Keep an encrypted copy of your workspace, credentials and records.'],help:['A few simple steps','Connect once. Choose a route. Prepare, then start when you are ready.'],wizard:['Set up a channel','Choose where videos come from and exactly where they will go.']};
function conns(kind){return Object.values(S.connections||{}).filter(c=>c.kind===kind);}
function clients(){return Object.values(S.clients||{});}
function count(value){return value===undefined||value===null||value===''||!Number.isFinite(Number(value))?'Unavailable':new Intl.NumberFormat().format(Number(value));}
function stamp(value){return value?new Date(value).toLocaleString():'Not checked';}
function ago(value){if(!value)return 'Unavailable';const n=Math.max(0,Math.floor((Date.now()-Date.parse(value))/60000));return n<1?'Just now':n<60?n+' min ago':n<1440?Math.floor(n/60)+' h ago':Math.floor(n/1440)+' days ago';}
function chip(text,kind=''){return '<span class="chip '+esc(kind)+'">'+esc(text)+'</span>';}
function button(text,action,id='',klass=''){return '<button class="'+klass+'" data-action="'+esc(action)+'"'+(id?' data-id="'+esc(id)+'"':'')+'>'+esc(text)+'</button>';}
function link(text,href,klass='button',tab=false){if(!/^(?:\/(?!\/)|https?:\/\/)/.test(String(href)))href='/#help';return '<a class="'+klass+'" href="'+esc(href)+'"'+(tab?' target="_blank" rel="noopener noreferrer"':'')+'>'+esc(text)+'</a>';}
function pic(c,size=''){const name=c?.label||c?.channel_title||c?.name||'?';const url=c?.avatar||S.connections[c?.youtube_connection]?.avatar;return '<span class="avatar '+size+'">'+(url&&/^\/avatars\/[a-f0-9]{64}\.img$/.test(url)?'<img src="'+esc(url)+'" alt="" loading="lazy">':'')+'<span>'+esc(name.trim().split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase())+'</span></span>';}
function empty(title,text,cta=''){return '<div class="empty"><h3>'+esc(title)+'</h3><p>'+esc(text)+'</p>'+cta+'</div>';}
function options(rows,value='',blank='Choose an account'){return '<option value="">'+esc(blank)+'</option>'+rows.map(c=>'<option value="'+esc(c.id)+'"'+(c.id===value?' selected':'')+'>'+esc(c.label||c.name||c.login)+'</option>').join('');}
function input(name,label,value='',type='text',extra=''){return '<label>'+esc(label)+'<input name="'+esc(name)+'" type="'+type+'" value="'+esc(value)+'" '+extra+'></label>';}
function select(name,label,rows,value='',blank='Choose an account'){return '<label>'+esc(label)+'<select name="'+esc(name)+'">'+options(rows,value,blank)+'</select></label>';}
function fieldData(form){const result=Object.fromEntries(new FormData(form));form.querySelectorAll('input[type=checkbox][name]').forEach(x=>result[x.name]=x.checked);return result;}
function googleEmail(c,compact=false){const account=c?.kind==='youtube'?c:S.connections[c?.youtube_connection];const known=account?.google_email_verified&&account.google_email;const email=known?account.google_email:'';if(compact)return '<small class="google-email">Google sign-in: '+esc(email||(account?.google_email_status==='Needs permission'?'Reconnect to fetch email':'Email not shared yet'))+'</small>';return '<div class="google-email">'+(known?'<strong class="email-value">'+esc(email)+'</strong><small>Verified '+esc(ago(account.google_email_checked_at))+'</small>':'<span class="muted">Email not shared yet</span><small>Reconnect once to fetch the Google email.</small>')+(account?.google_email_notice?'<small>'+esc(account.google_email_notice)+'</small>':'')+'</div>';}
function routeName(c){return 'Drive · '+(c.folder_path||c.folder_name||'Choose subfolder');}

function route(c){return '<div class="route"><div class="route-node">'+chip('Google Drive','neutral')+'<strong>'+esc(c.folder_path||c.folder_name||'Choose a subfolder')+'</strong><small>Videos come from here</small></div><span class="arrow">→</span><div class="route-node">'+pic(c)+'<strong>'+esc(c.channel_title||c.name)+'</strong>'+googleEmail(c,true)+'<small>Videos publish here</small></div></div><p class="help">Runs on Azure · '+Number(c.max_uploads_per_day||2)+' attempts per day</p>'; }
function dependencyIssues(c){return [c.youtube_connection,c.drive_connection].map(id=>S.connections[id]).filter(row=>row&&row.status!=='Connected');}
function reason(c){const issues=dependencyIssues(c);return issues.length?issues.map(row=>row.label+': '+(row.notice||row.status)).join(' · '):c.notice||c.status||'No issue recorded';}
function status(c){if(dependencyIssues(c).length)return ['Needs you','bad','attention'];if(c.needs_drive_folder)return ['Choose Drive folder','warn','attention'];if(c.status==='Needs attention'||/expired|revoked|mismatch|uncertain|failed/i.test(c.notice||'')||c.last_run?.conclusion==='failure')return ['Needs you','bad','attention'];if(c.enabled)return ['Running','','running'];return [c.deployed?'Paused':'Not prepared','neutral','paused'];}
function next(c){const n=c.next_schedule||{},video=c.next_video||n.next_video;return '<div class="next-publication">'+(n.next_at?'<span class="countdown" data-at="'+esc(n.next_at)+'"></span>':'<span>'+esc(n.label||'Not started')+'</span>')+'<small>'+esc(n.label||'Next Drive check')+'</small>'+(video?'<small class="next-filename">Next: '+esc(video.name)+'</small>':'<small>No new video in the last Drive check</small>')+'</div>';}
function isTestVideo(v){return !v.youtube_id&&/^dry[ _-]*run$/i.test(String(v.status||'').trim());}
function uniqueVideos(rows=R.uploads||[]){const bySource=new Map();const rank=v=>v.youtube_id?3:isTestVideo(v)?0:1;for(const row of rows){const key=row.client_id+':'+row.file_id;const previous=bySource.get(key);if(!previous||rank(row)>rank(previous))bySource.set(key,row);}return [...bySource.values()];}
function videoVisibility(v){if(isTestVideo(v))return {label:'Test only — no upload',kind:'neutral',key:'test',detail:'Scanned in a dry run. No YouTube upload was requested.'};const known=['public','private','unlisted'].includes(v.actual_privacy);if(known)return {label:v.actual_privacy[0].toUpperCase()+v.actual_privacy.slice(1),kind:v.actual_privacy==='public'?'':v.actual_privacy==='private'?'warn':'neutral',key:v.actual_privacy,detail:v.status||'Recorded'};return {label:v.youtube_id?'Visibility not checked':'Upload not confirmed',kind:'warn',key:'unknown',detail:v.youtube_id?'Upload ID saved. Sync stats to verify its visibility.':'Review the worker result before retrying an uncertain upload.'};}
function videoRows(rows){return rows.map(v=>{const visibility=videoVisibility(v),test=isTestVideo(v);return '<tr><td data-label="Video"><strong>'+esc(v.title||v.filename||'Video')+'</strong><small>'+stamp(v.recorded_at)+'</small><div class="actions">'+(v.youtube_url?link('YouTube ↗',v.youtube_url,'',true):'')+'</div></td><td data-label="Channel">'+link(S.clients[v.client_id]?.channel_title||v.client_name||v.client_id,'/channels/'+encodeURIComponent(v.client_id),'',true)+'</td><td data-label="YouTube visibility">'+chip(visibility.label,visibility.kind)+(test?'':'<small>Requested: '+esc(['public','private','unlisted'].includes(v.requested_privacy)?v.requested_privacy:'Not recorded')+'</small>')+'<small>'+esc(visibility.detail)+'</small></td><td data-label="YouTube views / likes / comments">'+(test?'<span class="muted">Not uploaded</span><small>Test run · no upload stats</small>':[v.youtube_views,v.youtube_likes,v.youtube_comments].map(count).join(' / ')+'<small>Checked: '+esc(stamp(v.stats_checked_at))+'</small><small>'+esc(v.stats_notice||'')+'</small>')+'</td></tr>';}).join('');}

function videoTable(rows){return rows.length?'<div class="table-wrap"><table><thead><tr><th>Video</th><th>Channel</th><th>Visibility</th><th>YouTube views / likes / comments</th></tr></thead><tbody>'+videoRows(rows)+'</tbody></table></div>':empty('No videos recorded yet','Connecting an account does not publish a video. Prepare and start a route when you are ready.');}
function toast(text,bad=false){$('toast').textContent=text;$('toast').className='notice'+(bad?' bad':'');}
async function api(path,body){const response=await fetch(path,{method:body===undefined?'GET':'POST',headers:{'X-Setup-Token':TOKEN,...(body===undefined?{}:{'Content-Type':'application/json'})},...(body===undefined?{}:{body:JSON.stringify(body)})});if(response.status===401){location.href='/login';throw Error('Sign in required.');}const result=await response.json();if(!response.ok)throw Error(result.error||'Request failed.');return result;}
async function refresh(force=false){const [state,records]=await Promise.all([api('/api/state'),api('/api/records')]);S=state;R=records;const completed=lastJob&&lastJob!=='idle'&&!S.job.busy;lastJob=S.job.busy?'running':'';chrome();if(force||completed||!document.querySelector('dialog[open]')&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))render();if(completed&&S.job.outcome==='error')toast(S.job.notice,true);if(pendingResult&&!S.job.busy){const callback=pendingResult;pendingResult=null;if(S.job.outcome==='error')toast(S.job.notice,true);else callback(S.job.result||{});} }
async function action(path,body={},callback=null){if(S.job.busy||busy)throw Error('Another operation is finishing. Your workers continue independently.');if(!S.unlocked&&path!=='/api/unlock')throw Error('Unlock your connections first.');busy=true;try{await api(path,body);pendingResult=callback;lastJob='running';await refresh();}finally{busy=false;}}
function modal(title,html){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;if(!$('modal').open)$('modal').showModal();}
function formFeedback(form,text,bad=false){let box=form.querySelector('.form-feedback');if(!box){box=document.createElement('div');box.setAttribute('role','status');box.className='form-feedback';form.append(box);}box.className='form-feedback notice'+(bad?' bad':'');box.textContent=text;return box;}
function googleAuthorizationProgress(){const form=$('googleConnectForm');if(!form||form.dataset.authPending!=='true')return;const job=S.job||{},submit=form.querySelector('button:not([data-action])');if(submit)submit.disabled=!!job.busy;const box=formFeedback(form,job.busy?(job.auth_url?'Your Google sign-in link is ready. Open it, choose the intended account and channel, then return here.':job.notice||'Creating your Google sign-in link…'):job.outcome==='error'?job.notice:'Authorization completed. Your saved account has been updated.',job.outcome==='error');if(job.busy&&job.auth_url)box.innerHTML='<p>Your Google sign-in link is ready. Choose the intended account and channel, then return here.</p><div class="actions">'+link('Open Google sign-in ↗',job.auth_url,'button primary',true)+button('Copy sign-in link','copy-auth')+button('Open private window','private-auth')+'</div>';if(!job.busy)delete form.dataset.authPending;}
function reviewChannel(id){const c=S.clients[id];if(!c)throw Error('Channel no longer exists.');modal('Review channel','<h3>'+esc(c.channel_title||c.name)+'</h3><p>'+esc(reason(c))+'</p><div class="actions">'+link('Open channel details','/channels/'+encodeURIComponent(id),'button',true)+link('Review folder matching','/#matching','button')+button('Delete channel','delete-channel',id,'danger')+'</div>');}
function resultTable(result){const rows=result.rows||[];return '<div class="table-wrap"><table><thead><tr><th>Channel / row</th><th>Result</th><th>Details</th></tr></thead><tbody>'+rows.map(r=>'<tr><td data-label="Channel">'+esc(r.name||r.data?.name||r.line||r.id)+'</td><td data-label="Result">'+esc(r.status||(r.blockers?.length?'Blocked':'Ready'))+'</td><td data-label="Details">'+esc((r.blockers||[]).join(' · ')||r.notice||r.reason||'')+'</td></tr>').join('')+'</tbody></table></div>';}
function chrome(){const locked=!S.unlocked;$('unlock').classList.toggle('hidden',!locked);$('unlockHeading').textContent=S.vault_exists?'Unlock your saved connections':'Create your backup unlock password';$('freshness').textContent='Last workspace sync: '+stamp(S.last_sync);$('workspaceMode').textContent=S.isolated_user?'Your private workspace':'Local workspace';const job=S.job||{};googleAuthorizationProgress();$('job').classList.toggle('hidden',!job.busy);if(job.busy)$('job').innerHTML='<div class="row wrap"><strong class="grow">'+esc(job.label||'Working')+'</strong>'+chip('In progress','neutral')+'</div><p class="help">'+esc(job.notice||'')+'</p>'+(job.auth_url?'<div class="link-box">Authorization link ready. Use your intended account in your chosen browser profile.</div><div class="actions">'+link('Open in this browser',job.auth_url,'button primary',true)+button('Copy link','copy-auth')+button('Open private window','private-auth')+'</div>':'')+(job.output?'<pre>'+esc(job.output)+'</pre>':'');}
function navigate(){const path=location.pathname.match(/^\/channels\/([^/]+)$/);current=path?'detail':({'clients':'channels','records':'videos','connections':'youtube','source':'drive'}[location.hash.slice(1)]||location.hash.slice(1)||'dashboard');if(current==='github'){current='dashboard';history.replaceState(null,'','/#dashboard');}if(!titles[current]&&current!=='detail')current='dashboard';$('sidebar').classList.remove('open');$('menuButton').setAttribute('aria-expanded','false');render();}
function render(){if(!S.workspace_id)return;for(const id of [...selected])if(!S.clients[id])selected.delete(id);$('navigation').innerHTML=pages.map(([id,label,icon],i)=>(id==='youtube'?'<div class="nav-group">Connections</div>':id==='automation'?'<div class="nav-group">Tools</div>':'')+'<a class="nav-link '+(current===id||current==='detail'&&id==='channels'?'active':'')+'" href="/#'+id+'"><span class="nav-icon" aria-hidden="true">'+icon+'</span>'+label+'</a>').join('');const title=titles[current]||['Channel details','Verified destination, route, statistics and history.'];$('heading').textContent=title[0];$('subtitle').textContent=title[1];$('headerActions').innerHTML=headerActions();const renderers={dashboard:dashboard,channels:channelList,videos:videos,recent:recentPosts,youtube:youtube,drive:drive,telegram:telegram,automation:automation,backup:backup,help:help,wizard:wizard,detail:detail,matching:matching,server:serverPage};$('content').innerHTML=renderers[current]();if(S.cloud?.hosted){$('remoteForm')?.closest('article')?.remove();document.querySelectorAll('[data-action=private-auth]').forEach(e=>e.remove());}if(Number.isInteger(S.cloud?.trial_days_remaining)&&S.cloud.trial_days_remaining<=3&&S.cloud.trial_days_remaining>=0)$('content').insertAdjacentHTML('afterbegin','<div class="notice warn">Azure trial ends in '+S.cloud.trial_days_remaining+' day(s). Verify backups and choose continuation or restore before '+esc(S.cloud.trial_ends)+'.</div>');document.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>img.parentElement.classList.add('failed'),{once:true}));countdowns();if(current==='wizard')updateRoutePreview();}
function forceNowButton(c){const rid=c.cloud_route_id||c.id,r=(S.cloud?.routes||[]).find(r=>r.id===rid);if(!r)return '';const p=r.plan||{},disabled=!S.cloud?.live_uploads||!r.history_verified||p.kind==='active'||p.kind==='attention'||p.daily_remaining===0;const why=!r.history_verified?'Confirm channel setup first':p.daily_remaining===0?'Daily limit reached':p.kind==='active'?'A check or upload is already queued':!S.cloud?.live_uploads?'Posting is off':'Post one new video as Public now';return '<button class="primary" data-action="cloud-now" data-id="'+esc(rid)+'" title="'+esc(why)+'"'+(disabled?' disabled':'')+'>Post force now</button>';}
function forceNowSection(){const ready=(S.cloud?.routes||[]).filter(r=>r.history_verified);return '<article class="card"><h2>Post force now</h2><p class="help">Check Drive and publish one new video as Public. Daily limits and duplicate protection still apply.</p>'+(ready.length?ready.slice(0,5).map(r=>{const c=S.clients[r.config.original_client_id]||S.clients[r.id]||{...r.config,cloud_route_id:r.id},p=r.plan||{};return '<div class="item wrap">'+pic(c)+'<div class="grow"><strong>'+esc(r.config.name)+'</strong><small>'+esc(p.next_video?.name||'Checks Drive for the next new video')+'</small><small>'+Number(p.daily_remaining??r.config.max_uploads_per_day)+' of '+r.config.max_uploads_per_day+' attempts left today</small></div>'+forceNowButton(c)+'</div>';}).join(''):empty('Confirm a folder/channel first','Your saved YouTube authorization is not a posting route yet.',link('Open folder matching','/#matching','button')))+'</article>';}
function headerActions(){if(current==='dashboard')return chip(S.cloud?.live_uploads?'Posting available':'Posting off','neutral')+button('Refresh data','sync');if(current==='channels')return link('Match a folder','/#matching','button')+button('+ Authorize channel','connect-youtube','','primary');if(current==='recent')return button('Sync stats','sync','','primary');if(current==='videos')return button('Download CSV','download-csv')+button('Sync stats','sync','','primary');if(current==='youtube')return button('Refresh photos','avatars')+button('+ Authorize channel','connect-youtube','','primary');return '';}
function setupChecklist(){const drive=!!S.drive_root&&conns('drive').some(c=>c.status==='Connected'),yt=conns('youtube').length,matches=(S.cloud?.matching||[]).filter(r=>r.ready).length,steps=[['1','Connect Drive',drive,'One main folder for your videos','/#drive'],['2','Authorize YouTube',yt>0,yt+' channel(s) connected','/#youtube'],['3','Match a folder',matches>0,matches+' exact name match(es)','/#matching']];return (S.primary_origin&&!S.cloud?.hosted?'<div class="notice"><strong>Use your online workspace</strong><p>This is the local preparation copy. Your Azure server runs the jobs.</p>'+link('Open DriveCast online',S.primary_origin,'button primary',true)+'</div>':'')+(S.google_app_ready===false?'<div class="notice warn"><strong>One-time Google API app setup</strong><p>Azure needs a Web OAuth client before you authorize channels. Add it once on the YouTube page.</p>'+link('Set up Google API app','/#youtube','button')+'</div>':'')+'<section class="card"><div class="section-head"><div><h2>'+(clients().length?'Your setup at a glance':'Let’s connect your first channel')+'</h2><p class="help">Google Drive → Azure → YouTube. '+(S.cloud?.live_uploads?'Only individually approved routes can post.':'Posting is off while you set up.')+'</p></div>'+chip('Azure workspace','neutral')+'</div><div class="grid cols3">'+steps.map(([n,title,done,note,href])=>'<a class="setup-step '+(done?'complete':'')+'" href="'+href+'"><span class="step-number">'+(done?'✓':n)+'</span><strong>'+title+'</strong><small>'+esc(note)+'</small><span>'+(done?'Review →':'Set up →')+'</span></a>').join('')+'</div></section>';}
// Recent posts use accepted YouTube IDs only; dry runs and uncertain checks stay in Videos.
function uploadTime(v){const time=Date.parse(v.recorded_at);return Number.isFinite(time)?time:0;}
function uploadedVideos(){
 const accepted=new Map();
 for(const v of [...(R.uploads||[])].filter(v=>v.youtube_id).sort((a,b)=>uploadTime(b)-uploadTime(a))){
  const c=S.clients[v.client_id],key=(c?.channel_id||v.client_id)+':'+v.youtube_id;
  if(!accepted.has(key))accepted.set(key,v);
 }
 return [...accepted.values()];
}
function latestChannelPosts(rows=uploadedVideos()){
 const latest=new Map();
 for(const v of rows){const key=S.clients[v.client_id]?.channel_id||v.client_id;if(!latest.has(key))latest.set(key,v);}
 return [...latest.values()];
}
function recentStats(value,label,checked){
 const known=value!==null&&value!==undefined&&value!==''&&Number.isFinite(Number(value));
 return '<td class="recent-number" data-label="'+label+'" title="'+esc(checked?'Stats checked: '+stamp(checked):'Stats not checked')+'"><span>'+ (known?count(value):'—')+'</span></td>';
}
function recentPostTable(rows,latest=false){
 if(!rows.length)return '<div class="recent-empty"><strong>No uploads yet</strong><span>Accepted uploads appear here automatically. Dry runs stay in Videos.</span></div>';
 return '<div class="recent-table-wrap"><table class="recent-table"><caption class="sr-only">'+(latest?'Latest upload per channel':'Recent uploaded videos')+' with last-known YouTube counters</caption><thead><tr><th>Channel</th><th>'+(latest?'Latest post':'Post')+'</th><th class="recent-number">Views</th><th class="recent-number">Likes</th><th class="recent-number">Comments</th></tr></thead><tbody>'+rows.map(v=>{
  const c=S.clients[v.client_id]||{name:v.client_name||v.client_id},name=c.channel_title||c.name,visibility=videoVisibility(v);
  const visibilityLabel=visibility.key==='unknown'?'Visibility not checked':visibility.label;
  const channelLink='/channels/'+encodeURIComponent(v.client_id),videoLink='https://youtu.be/'+encodeURIComponent(v.youtube_id);
  return '<tr data-video-id="'+esc(v.youtube_id)+'"><td class="recent-channel"><div class="row">'+pic(c)+link(name,channelLink,'item-name',true)+'</div></td><td class="recent-post">'+link(v.title||v.filename||'Video',videoLink,'recent-title',true)+'<div class="recent-meta"><span title="Recorded: '+esc(stamp(v.recorded_at))+'">'+esc(v.recorded_at?ago(v.recorded_at):'Time unavailable')+'</span>'+chip(visibilityLabel,visibility.kind)+'</div></td>'+recentStats(v.youtube_views,'Views',v.stats_checked_at)+recentStats(v.youtube_likes,'Likes',v.stats_checked_at)+recentStats(v.youtube_comments,'Comments',v.stats_checked_at)+'</tr>';
 }).join('')+'</tbody></table></div>';
}
function recentDashboard(){
 const rows=latestChannelPosts(),limit=6;
 return '<section class="card recent-card" id="recent-posts" aria-labelledby="recentHeading"><div class="section-head"><div><h2 id="recentHeading">Recent posts</h2><small>Latest per channel · last-known stats</small></div>'+link('View all →','/#recent','text-link')+'</div>'+recentPostTable(rows.slice(0,limit),true)+(rows.length>limit?'<div class="recent-footer">'+link('View all '+rows.length+' channels','/#recent','text-link')+'</div>':'')+'</section>';
}
function recentPosts(){
 const uploads=uploadedVideos(),byClient=new Map();
 for(const v of uploads)if(!byClient.has(v.client_id))byClient.set(v.client_id,{id:v.client_id,label:S.clients[v.client_id]?.channel_title||S.clients[v.client_id]?.name||v.client_name||v.client_id});
 const channels=[...byClient.values()].sort((a,b)=>a.label.localeCompare(b.label));
 // Pick each channel's latest before applying title search, so an older matching post cannot masquerade as its latest.
 let rows=recentFilters.mode==='latest'?latestChannelPosts(uploads):uploads;
 rows=rows.filter(v=>(!recentFilters.client||v.client_id===recentFilters.client)&&(!recentFilters.search||[v.title,v.filename,v.youtube_id,v.client_name,S.clients[v.client_id]?.channel_title].join(' ').toLowerCase().includes(recentFilters.search.toLowerCase())));
 const size=20,pages=Math.max(1,Math.ceil(rows.length/size));recentPage=Math.min(recentPage,pages-1);
 return '<div class="filters recent-filters"><label>Find a post<input id="recentSearch" type="search" placeholder="Video, channel or ID…" value="'+esc(recentFilters.search)+'"></label><label>Channel<select id="recentClient">'+options(channels,recentFilters.client,'All channels')+'</select></label><label>Show<select id="recentMode"><option value="all"'+(recentFilters.mode==='all'?' selected':'')+'>All uploads</option><option value="latest"'+(recentFilters.mode==='latest'?' selected':'')+'>Latest per channel</option></select></label>'+button('Clear','clear-recent')+'</div><section class="card recent-card" aria-label="Recent post results"><div class="section-head"><small>'+rows.length+' post'+(rows.length===1?'':'s')+' · newest first</small><small>— = stats not checked</small></div>'+recentPostTable(rows.slice(recentPage*size,(recentPage+1)*size),recentFilters.mode==='latest')+'<div class="paging"><small>Page '+(recentPage+1)+' of '+pages+'</small><div class="actions"><button data-action="previous-recent"'+(!recentPage?' disabled':'')+'>Previous</button><button data-action="next-recent"'+(recentPage>=pages-1?' disabled':'')+'>Next</button></div></div></section>';
}
function dashboard(){
 const list=clients(),running=list.filter(c=>c.enabled).length,needs=list.filter(c=>status(c)[2]==='attention'),rows=uniqueVideos(),uploaded=uploadedVideos();
 const today=new Date().toLocaleDateString('en-CA'),published=uploaded.filter(v=>v.actual_privacy==='public'&&new Date(v.recorded_at).toLocaleDateString('en-CA')===today).length;
 const nextList=list.filter(c=>c.enabled).sort((a,b)=>(a.next_schedule?.next_at||'').localeCompare(b.next_schedule?.next_at||''));
 const known=uploaded.filter(v=>v.youtube_views!==null&&v.youtube_views!==undefined),views=known.length?known.reduce((sum,v)=>sum+Number(v.youtube_views),0):null;
 const metric=(label,value,note,href)=>'<a class="card kpi" href="'+href+'"><span>'+label+'</span><strong>'+value+'</strong><small>'+esc(note)+'</small></a>';
 let result='<div class="kpis dashboard-kpis">'+metric('Channels',list.length,running+' running · '+needs.length+' need you','/#channels')+metric('Video views',count(views),known.length+' uploads with saved stats','/#recent')+metric('Public today',published,'Verified Public uploads','/#recent')+metric('Next video check',nextList[0]?.next_schedule?.next_at?'<span class="countdown" data-at="'+esc(nextList[0].next_schedule.next_at)+'"></span>':esc(nextList[0]?.next_schedule?.label||'Not planned'),nextList[0]?.channel_title||'No active channel','/#channels')+'</div>';
 result+=recentDashboard();
 result+='<div class="grid dashboard-grid"><div><article class="card"><div class="section-head"><h2>Next up</h2>'+link('All channels →','/#channels','text-link')+'</div>'+(nextList.length?nextList.slice(0,4).map(c=>'<div class="item">'+pic(c)+'<div class="grow">'+link(c.channel_title||c.name,'/channels/'+encodeURIComponent(c.id),'item-name',true)+'</div><div class="next-summary">'+next(c)+'</div></div>').join(''):'<p class="help">No active channel. Match a folder and confirm its destination to begin.</p>')+'</article><article class="card"><div class="section-head"><h2>Upload activity</h2><select id="chartPeriod" aria-label="Activity period"><option value="7"'+(chartPeriod===7?' selected':'')+'>Last 7 days</option><option value="30"'+(chartPeriod===30?' selected':'')+'>Last 30 days</option></select></div>'+activityBars(uploaded)+'</article></div><div><article class="card"><h2>Needs your attention'+(needs.length?' ('+needs.length+')':'')+'</h2>'+(needs.length?needs.slice(0,5).map(c=>'<div class="item">'+pic(c)+'<div class="grow">'+link(c.channel_title||c.name,'/channels/'+encodeURIComponent(c.id),'item-name',true)+'<small>'+esc(reason(c))+'</small></div>'+button('Review','open-channel',c.id)+'</div>').join(''):'<p class="help calm-status">✓ No channel issues in the latest checks</p>')+'</article><article class="card"><h2>Top channels</h2>'+topChannels(uploaded)+'</article><article class="card"><div class="section-head"><h2>Automation</h2>'+link('Details →','/#automation','text-link')+'</div><div class="row wrap">'+chip(running+' running')+chip((S.cloud?.workers||[]).filter(w=>Date.now()/1000-w.last_seen<120).length+' workers online','neutral')+'</div><small>Last sync: '+esc(stamp(S.last_sync))+'</small></article></div></div>';
 return result+forceNowSection()+setupChecklist();
}
function activityBars(rows){const dates=Array.from({length:chartPeriod},(_,i)=>{const d=new Date();d.setDate(d.getDate()-chartPeriod+i+1);return d.toLocaleDateString('en-CA');});const counts=dates.map(day=>rows.filter(v=>new Date(v.recorded_at).toLocaleDateString('en-CA')===day).length);const max=Math.max(1,...counts);return '<div class="bars">'+dates.map((day,i)=>'<div class="bar-col"><button data-height="'+Math.max(2,counts[i]/max*125)+'" data-action="bar-videos" data-id="'+day+'" aria-label="'+day+': '+counts[i]+' recorded videos" title="'+counts[i]+' records"></button><small>'+day.slice(8)+'</small></div>').join('')+'</div>';}
function topChannels(rows){const totals=clients().map(c=>{const known=rows.filter(v=>v.client_id===c.id&&v.youtube_views!==null&&v.youtube_views!==undefined);return {c,total:known.length?known.reduce((a,v)=>a+Number(v.youtube_views),0):null};}).sort((a,b)=>(b.total??-1)-(a.total??-1)).slice(0,5);const max=Math.max(1,...totals.map(r=>r.total||0));return totals.length?totals.map(r=>'<div class="item">'+pic(r.c)+'<div class="grow">'+link(r.c.channel_title||r.c.name,'/channels/'+r.c.id,'item-name',true)+'<small>'+count(r.total)+' views · last-known video counters</small>'+(r.total!==null?'<div class="bar-track"><div class="bar-fill" data-width="'+r.total/max*100+'"></div></div>':'')+'</div></div>').join(''):empty('No channel stats yet','A successful stats sync will populate this list.');}
function filteredChannels(){return clients().filter(c=>(!filters.search||[c.name,c.channel_title,c.folder_path,c.folder_name,c.channel_id,c.repo_name,S.connections[c.youtube_connection]?.google_email,...(c.tags||[])].join(' ').toLowerCase().includes(filters.search.toLowerCase()))&&(!filters.status||status(c)[2]===filters.status)&&(!filters.source||c.source_type===filters.source)&&(!filters.tag||(c.tags||[]).includes(filters.tag))).sort((a,b)=>(a.channel_title||a.name).localeCompare(b.channel_title||b.name));}
function channelList(){const all=clients(),rows=filteredChannels(),size=20;page=Math.min(page,Math.max(0,Math.ceil(rows.length/size)-1));let html='<div class="filter-pills">'+[['','All '+all.length],['running','Running '+all.filter(c=>status(c)[2]==='running').length],['paused','Paused '+all.filter(c=>status(c)[2]==='paused').length],['attention','Needs you '+all.filter(c=>status(c)[2]==='attention').length]].map(([id,label])=>button(label,'filter-status',id,filters.status===id?'selected':'')).join('')+'</div><div class="filters"><label>Find a channel or folder<input id="fleetSearch" value="'+esc(filters.search)+'" placeholder="Channel name, email or folder…" type="search"></label><label>Status<select id="fleetStatus">'+options([{id:'running',label:'Running'},{id:'paused',label:'Paused'},{id:'attention',label:'Needs you'}],filters.status,'All statuses')+'</select></label>'+button('Clear filters','clear-filters')+'</div>';
if(!all.length)return html+setupChecklist()+empty('Your channels start here',conns('youtube').length+' YouTube channel(s) authorized · '+(S.cloud?.routes||[]).length+' folder preview(s). Authorize a channel and match its Drive folder to create a route.',link('Match a folder','/#matching','button primary'));
html+='<div class="card row wrap"><strong class="grow" id="selectedCount">'+selected.size+' selected</strong>'+button('Delete selected','delete-selected','','danger')+'</div><div class="card table-card"><div class="table-wrap"><table><thead><tr><th><input type="checkbox" id="selectPage" aria-label="Select this page"></th><th>Channel</th><th>Drive → YouTube</th><th>Status</th><th>Recorded views</th><th>Next check</th><th>Actions</th></tr></thead><tbody>'+rows.slice(page*size,(page+1)*size).map(c=>{const st=status(c),v=uniqueVideos().filter(v=>v.client_id===c.id&&v.youtube_views!=null),rid=c.cloud_route_id;return '<tr><td><input type="checkbox" data-select="'+esc(c.id)+'" aria-label="Select '+esc(c.name)+'"'+(selected.has(c.id)?' checked':'')+'></td><td data-label="Channel"><div class="row">'+pic(c)+link(c.channel_title||c.name,'/channels/'+c.id,'item-name',true)+'</div>'+googleEmail(c,true)+'<small>'+esc(c.channel_id)+'</small></td><td data-label="Drive → YouTube">'+esc(c.folder_path||c.folder_name||'Choose folder')+'<small>Azure · '+Number(c.max_uploads_per_day||2)+' attempts/day</small></td><td data-label="Status">'+chip(st[0],st[1])+'</td><td data-label="Recorded views">'+count(v.length?v.reduce((n,v)=>n+Number(v.youtube_views),0):null)+'</td><td data-label="Next check">'+next(c)+'</td><td><div class="actions">'+forceNowButton(c)+(rid?button('Dry run','cloud-dry',rid)+(c.enabled?button('Pause','cloud-pause',rid):S.cloud?.live_uploads?button('Start Public','cloud-start',rid):''):link('Choose folder','/#matching','button'))+button('Delete','delete-channel',c.id,'danger')+'</div></td></tr>';}).join('')+'</tbody></table></div><div class="paging"><span class="help">'+(rows.length?page*size+1:0)+'–'+Math.min((page+1)*size,rows.length)+' of '+rows.length+'</span><div class="actions">'+button('Previous','previous-channels')+button('Next','next-channels')+'</div></div></div>';return html; }
function detail(){const key=decodeURIComponent(location.pathname.split('/').pop()),c=S.clients[key]||clients().find(c=>c.channel_id===key);if(!c){const yt=conns('youtube').find(y=>y.channel_id===key);if(yt)return unassignedDetail(yt);return empty('Channel removed','Authorize the channel again when you want to use it.',link('Open YouTube','/#youtube','button'));}const yt=S.connections[c.youtube_connection]||{},st=status(c),rid=c.cloud_route_id;const stats=c.stats||yt.stats||{};$('heading').textContent=c.channel_title||c.name;return '<article class="card"><div class="section-head"><div class="row">'+pic(c,'large')+'<div><h2>'+esc(c.channel_title||c.name)+'</h2>'+googleEmail(c)+'<small>'+esc(c.channel_id)+'</small></div></div>'+chip(st[0],st[1])+'</div>'+route(c)+'<div class="actions">'+forceNowButton(c)+(rid?button('Read-only test','cloud-dry',rid)+(c.enabled?button('Pause','cloud-pause',rid):S.cloud?.live_uploads?button('Start Public','cloud-start',rid):''):'')+link('Folder settings','/#matching','button')+button('Delete channel','delete-channel',c.id,'danger')+'</div></article><div class="kpis">'+[['Subscribers',stats.hiddenSubscriberCount==='true'||stats.hiddenSubscriberCount===true?null:stats.subscriberCount],['Lifetime views',stats.viewCount],['Channel videos',stats.videoCount],['Views · last 30 days',yt.analytics?.views_30d]].map(([label,n])=>'<article class="card kpi"><span>'+label+'</span><strong>'+count(n)+'</strong><small>Checked: '+stamp(stats.checked_at||yt.checked_at)+'</small></article>').join('')+'</div><article class="card"><h2>Recorded videos</h2>'+videoTable(uniqueVideos().filter(v=>v.client_id===c.id))+'</article>'; }
function videos(){let rows=uniqueVideos().filter(v=>(!videoFilters.client||v.client_id===videoFilters.client)&&(!videoFilters.search||[v.title,v.filename,v.youtube_id,v.client_name].join(' ').toLowerCase().includes(videoFilters.search.toLowerCase()))&&(!videoFilters.status||videoVisibility(v).key===videoFilters.status)&&(!recordDay||new Date(v.recorded_at).toLocaleDateString('en-CA')===recordDay));videoPage=Math.min(videoPage,Math.max(0,Math.ceil(rows.length/20)-1));return '<div class="filters">'+select('videoClient','Channel',clients(),videoFilters.client,'All channels').replace('name="videoClient"','id="videoClient"')+'<label>Find a video<input id="videoSearch" type="search" placeholder="Title or video ID…" value="'+esc(videoFilters.search)+'"></label><label>Actual visibility<select id="videoStatus">'+options([{id:'public',label:'Public'},{id:'private',label:'Private'},{id:'unlisted',label:'Unlisted'},{id:'unknown',label:'Visibility not verified'},{id:'test',label:'Test only · no upload'}],videoFilters.status,'All visibility')+'</select></label>'+button('Clear filters','clear-videos')+'</div>'+(recordDay?'<p>Recorded on '+esc(recordDay)+'</p>':'')+'<article class="card table-card">'+videoTable(rows.slice(videoPage*20,(videoPage+1)*20))+'<div class="paging"><small>'+rows.length+' unique video records · page '+(videoPage+1)+' of '+Math.max(1,Math.ceil(rows.length/20))+'</small><div class="actions">'+button('Previous','previous-videos')+button('Next','next-videos')+'</div></div></article><p class="help">Test-only rows were scanned without uploading. Unavailable counters are never replaced with zero. A Public request is not proof of Public publication. An accepted video is never automatically uploaded again.</p>';}
function googleApp(){return '<article class="card"><div class="section-head"><h2>Your Google API app</h2>'+chip(S.google_app_ready===false?'Web app setup required':S.google_json_saved?'Saved · secret encrypted':'Add once',S.google_app_ready===false?'warn':S.google_json_saved?'':'neutral')+'</div><p class="muted">One Google OAuth app is reused for YouTube and Drive. Each channel is authorized and verified separately.</p>'+(S.google_app?.client_id?'<p class="help">Client ID: '+esc(S.google_app.client_id)+'</p>':'')+(S.web_callbacks?'<p class="help">Use a Web application OAuth client. Register this exact Google redirect URI:</p><div class="link-box">'+esc(S.web_callbacks.google)+'</div>':'')+'<details'+(!S.google_json_saved||S.google_app_ready===false?' open':'')+'><summary>'+(S.google_json_saved?'Replace API app settings':(S.web_callbacks?'Add your Web OAuth app':'Add your Desktop OAuth app'))+'</summary><form id="googleAppForm"><div class="form-grid">'+input('client_id','Google client ID','','text','autocomplete="off"')+input('client_secret','Google client secret','','password','autocomplete="new-password"')+input('project_id','Google Cloud project ID (optional)')+'<label>Or upload the downloaded '+(S.web_callbacks?'Web':'Desktop')+' JSON<input type="file" name="oauth_file" accept=".json,application/json"></label></div><button>Save API app</button><p class="help">Enable YouTube Data API, YouTube Analytics API and Google Drive API in your project. Add your Google accounts as test users while your OAuth app is in testing.</p></form></details></article>';}
function youtube(){const list=conns('youtube');return googleApp()+'<article class="card"><div class="section-head"><div><h2>Your YouTube channels ('+list.length+')</h2><p class="help">Channel IDs and sign-in emails come from Google. The email identifies who authorized access; it does not establish the original channel creator.</p></div>'+button('+ Add channel','connect-youtube','','primary')+'</div>'+(list.length?'<div class="table-wrap"><table><thead><tr><th>Channel</th><th>Google sign-in email</th><th>Subscribers</th><th>Views · 30 days</th><th>Runner</th><th>Status</th><th></th></tr></thead><tbody>'+list.map(yt=>{const c=clients().find(c=>c.youtube_connection===yt.id),sub=yt.stats?.hiddenSubscriberCount==='true'||yt.stats?.hiddenSubscriberCount===true?null:yt.stats?.subscriberCount;return '<tr><td data-label="Channel"><div class="row">'+pic(yt)+'<div>'+link(yt.label,'/channels/'+(c?.id||yt.channel_id),'item-name',true)+'<small>'+esc(yt.channel_id)+'</small></div></div></td><td data-label="Google sign-in email">'+googleEmail(yt)+'</td><td data-label="Subscribers">'+count(sub)+'<small>'+ago(yt.checked_at)+'</small></td><td data-label="Views · 30 days">'+count(yt.analytics?.views_30d)+'<small>'+esc(yt.analytics?.start&&yt.analytics?.end?yt.analytics.start+' to '+yt.analytics.end:yt.analytics?.notice||'Analytics permission not connected')+'</small></td><td data-label="Runner">'+'Azure'+'</td><td data-label="Status">'+chip(yt.status,yt.status==='Connected'?'':'warn')+'<small>'+(c?'Route '+(c.enabled?'running':c.deployed?'paused':'not prepared'):'No route configured')+'</small></td><td><div class="actions">'+button(yt.google_email_verified?'Reconnect':'Reconnect to fetch email','connect-youtube',yt.id)+button('Delete channel','delete-channel',yt.id,'danger')+(c?forceNowButton(c):'')+link('Full stats ↗','/channels/'+(c?.id||yt.channel_id),'button',true)+(!c?button('Connect Drive folder','route-youtube',yt.id):'')+'</div></td></tr>';}).join('')+'</tbody></table></div>':empty('Connect your first YouTube channel','Enter the intended name first. Then open the authorization link in the browser profile you choose.',button('+ Add channel','connect-youtube','','primary')))+'</article>';}
function drive(){const root=S.drive_root,all=root?.folders||[],query=folderSearch.toLowerCase(),rows=all.filter(f=>[f.path,f.name,f.client_name].join(' ').toLowerCase().includes(query));folderPage=Math.min(folderPage,Math.max(0,Math.ceil(rows.length/30)-1));return '<div class="notice"><strong>One project folder → one subfolder per channel → YouTube.</strong><p>Connect Drive once. Refresh folders, select the channel’s subfolder, then confirm its exact YouTube destination.</p></div>'+(!S.google_json_saved?googleApp():'')+'<article class="card"><div class="section-head"><h2>1. Connect the project Drive account</h2>'+button(conns('drive').length?'Reconnect / add Drive account':'Connect Google Drive','connect-drive','','primary')+'</div>'+conns('drive').map(c=>'<div class="item"><div class="grow"><strong>'+esc(c.label)+'</strong><small>'+esc(c.status)+'</small></div>'+button('Reconnect','connect-drive',c.id)+'</div>').join('')+'<form id="driveRootForm"><h2>2. Your main folder</h2><div class="form-grid">'+select('connection_id','Drive account',conns('drive'),root?.connection_id||conns('drive')[0]?.id)+input('folder_id','Main folder link or ID',root?.folder_id||S.drive_project?.folder_id||'','text','required')+'</div><button class="primary">'+(root?'Refresh subfolders':'Save main folder and find subfolders')+'</button></form><p class="help">Nested subfolders are included. Processing, Done and Failed folders are hidden. Finding a folder never starts posting.</p></article><article class="card"><div class="section-head"><div><h2>3. Choose a channel subfolder</h2><small>'+esc(root?.name||'Connect the main folder first')+' · '+all.length+' subfolders · '+stamp(root?.checked_at)+'</small></div></div><label>Find a folder or linked channel<input id="folderSearch" type="search" placeholder="Folder name, path or channel" value="'+esc(folderSearch)+'"></label>'+(root?.notice||S.drive_project?.notice?'<p class="notice warn">'+esc(root?.notice||S.drive_project.notice)+'</p>':'')+(rows.length?rows.slice(folderPage*30,(folderPage+1)*30).map(f=>'<div class="item"><span class="avatar">△</span><div class="grow"><strong>'+esc(f.path||f.name)+'</strong><small>'+esc(f.client_name?'Linked to '+f.client_name:'Not assigned to a channel')+'</small></div>'+(f.client_id?link('Open channel','/channels/'+f.client_id,'button',true):button('Select this folder','folder-route',f.id))+'</div>').join(''):empty(all.length?'No matching folders':'No subfolders found','Create a subfolder for each channel, then refresh.'))+'<div class="paging"><small>'+rows.length+' folders · page '+(folderPage+1)+' of '+Math.max(1,Math.ceil(rows.length/30))+'</small><div class="actions">'+button('Previous','folder-previous')+button('Next','folder-next')+'</div></div></article>';}


function telegram(){const t=S.telegram||{},settings=t.settings||{uploads:true,failures:true,reconnect:true,failover:true,daily:true,weekly:true,daily_time:'20:00',timezone:'America/Los_Angeles',commands:false};return '<div class="grid cols2"><div><article class="card"><div class="section-head"><h2>Your Telegram bot</h2>'+chip(t.linked?'Connected':t.username?'Waiting for /start':'Not connected',t.linked?'':'neutral')+'</div>'+(t.username?'<p>@'+esc(t.username)+' · '+esc(t.chat_label||'Chat not linked')+'</p>':'<p class="muted">Create your own bot with BotFather, then save its token here.</p>')+'<form id="telegramBotForm">'+input('token','BotFather token','','password','required autocomplete="new-password"')+'<button>Save and verify bot</button></form><p class="help">The token is encrypted locally and never shown again.</p>'+(t.start_link?'<hr class="divider"><h3>Link your private chat</h3><p>Open Telegram and send /start using this pairing link. Only this private-chat pairing code can claim the bot.</p>'+link('Open Telegram',t.start_link,'button primary',true)+button('I sent /start · check link','telegram-link'):'')+(t.linked?'<div class="actions">'+button('Send test message','telegram-test')+'</div>':'')+'</article><article class="card"><h2>Commands</h2><pre>/today\n/stats\n/channel &lt;exact name&gt;\n/status\n/pause &lt;exact name&gt;\n/resume &lt;exact name&gt;</pre><p class="notice warn">Commands and reports run on your Azure server while it is online, including when your laptop is off.</p><p class="help">Link your private chat before enabling commands and automatic reports.</p></article></div><article class="card"><h2>Automatic reports</h2><p class="muted">Each report includes the counters we actually have, their checked time and “Unavailable” for missing data. Long reports are split into messages.</p><form id="telegramSettingsForm">'+[['uploads','Every upload'],['failures','Failures'],['reconnect','Reconnect alerts'],['failover','Worker health alerts'],['daily','Daily summary'],['weekly','Weekly stats'],['commands','Allow commands from the linked chat']].map(([key,label])=>'<label class="check"><input type="checkbox" name="'+key+'"'+(settings[key]?' checked':'')+'>'+label+'</label>').join('')+input('daily_time','Daily report time',settings.daily_time,'time')+input('timezone','Report time zone',settings.timezone)+'<button class="primary">Save report settings</button></form><p class="help">Reports use the saved counters and clearly show their last checked time.</p></article></div>';}
function automation(){return cloudAutomation();}
function backup(){return recoveryCard()+'<div class="grid cols2"><article class="card"><h2>Download your encrypted backup</h2><p>Includes this workspace, records and encrypted credentials.</p>'+button('Download backup','export-backup','','primary')+'<p class="help">Keep your recovery password separately.</p></article><article class="card"><h2>Restore from backup</h2><p>Preview before restoring. All restored channels stay paused.</p><form id="backupPreviewForm"><label>Encrypted .drivecast backup<input name="backup" type="file" accept=".drivecast" required></label>'+input('password','Original recovery password','','password','required autocomplete="current-password"')+'<button>Preview import</button></form></article></div><article class="card"><h2>Fresh start</h2><p>Clear all channels, saved platform authorizations, video records, stats and folder assignments from this workspace. Your login, Google API app settings and Telegram settings stay.</p><p>YouTube videos and Drive files are not deleted. An encrypted recovery copy is saved before cleanup. Fresh history cannot recognize earlier manual uploads; review your source folders before starting.</p>'+button('Reset channel workspace','reset-workspace','','danger')+'</article>'; }
function help(){return setupChecklist()+'<div class="grid cols2"><article class="card"><h2>Where do videos come from?</h2><p>Google Drive is the only source. Connect the account that can edit your project folder, then choose that main folder once. Put each channel’s videos directly in its own subfolder.</p></article><article class="card"><h2>Where do videos go?</h2><p>Authorize the intended YouTube channel. The returned channel ID and Google sign-in email are shown so you can verify the destination.</p></article><article class="card"><h2>When will it post?</h2><p>Match a folder and run a read-only test. After a separately approved go-live, eligible videos are published Public on the next Azure source check within the daily limit. Login or authorization alone does not start posting.</p></article><article class="card"><h2>Remove or start again</h2><p>Delete removes the selected channel’s saved access and local history. Backup → Fresh start resets every channel. An encrypted recovery checkpoint is kept. Provider videos/files remain in place.</p></article></div>'; }
function wizard(){return matching();}
function routeFormData(){const f=$('routeForm');if(!f)throw Error('Open channel setup first.');const d=fieldData(f);d.tags=d.tags.split(',').map(s=>s.trim()).filter(Boolean);d.max_uploads_per_day=Number(d.max_uploads_per_day);d.check_minutes=Number(d.check_minutes);if(!d.repo_name)d.repo_name='youtube-'+d.name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,60);if(!d.id){delete d.id;const existing=clients().find(c=>c.youtube_connection===d.youtube_connection&&c.needs_drive_folder);if(existing){d.id=existing.id;d.repo_name=existing.repo_name;d.github_connection=existing.github_connection;}}return d;}
function updateRoutePreview(){const f=$('routeForm');if(!f)return;const d=fieldData(f),yt=S.connections[d.youtube_connection],folder=S.drive_root?.folders?.find(x=>x.id===d.folder_id),gh=S.connections[d.github_connection];$('routePreview').innerHTML='<div class="route"><div class="route-node"><small>Drive subfolder</small><strong>'+esc(folder?.path||folder?.name||'Choose a folder')+'</strong></div><span class="arrow">→</span><div class="route-node">'+pic(yt)+'<strong>'+esc(yt?.label||'Choose the YouTube channel')+'</strong>'+googleEmail(yt,true)+'<small>'+esc(yt?.channel_id||'')+'</small></div></div><p class="help">Worker: '+esc(gh?.login||'auto-assign a healthy free slot')+'</p>';}

function countdowns(){document.querySelectorAll('[data-at]').forEach(el=>{let n=Math.ceil((Date.parse(el.dataset.at)-Date.now())/1000);el.textContent=n<=0?'Check due':n>=86400?Math.floor(n/86400)+'d '+Math.floor(n%86400/3600)+'h':n>=3600?Math.floor(n/3600)+'h '+Math.floor(n%3600/60)+'m':n>=60?Math.floor(n/60)+'m '+n%60+'s':n+'s';});document.querySelectorAll('[data-width]').forEach(el=>el.style.width=el.dataset.width+'%');document.querySelectorAll('[data-height]').forEach(el=>el.style.height=el.dataset.height+'px');}
function googleDialog(kind,id=''){if(S.cloud?.hosted&&S.google_app_ready===false){modal('One-time Google Web app setup','<p>The saved OAuth app is for a local desktop. Azure needs a Web application OAuth client before you can authorize Drive or YouTube.</p><p>Open Google API app settings on the YouTube page, add the Web client JSON and register the displayed HTTPS callback. Your login and channels are kept.</p>'+link('Open Google API app settings','/#youtube','button primary')+button('Close','close-modal'));return;}if(!S.google_json_saved){toast('Add your Google API app first.',true);location.href='/#youtube';return;}const c=S.connections[id];modal((c?'Reconnect ':'Authorize ')+(kind==='youtube'?'YouTube channel':'Google Drive'),'<p>We create a sign-in link. You choose which browser profile opens it. Verify the returned account before using it in a route.</p><form id="googleConnectForm">'+input('label',kind==='youtube'?'Exact intended channel name':'Account label',c?.label||'','text',kind==='youtube'?'required':'')+'<input type="hidden" name="kind" value="'+kind+'"><input type="hidden" name="id" value="'+esc(id)+'">'+(kind==='youtube'?'<p class="help">Google will also request your account email so it can be shown beside this channel.</p><label class="check"><input type="checkbox" name="analytics" checked> Request read-only channel analytics for 30-day views</label>':'<p class="help">Full Drive scope allows sub-folder discovery and moving completed files. This permission is reused for every client folder.</p>')+'<button class="primary">Create authorization link</button></form>');}


function confirmDialog(title,html,actionName){modal(title,html+'<div class="actions">'+button('Confirm','confirm',actionName,'primary')+button('Cancel','close-modal')+'</div>');}
async function download(path,name){const response=await fetch(path,{headers:{'X-Setup-Token':TOKEN}});if(!response.ok){let e=await response.json();throw Error(e.error||'Download failed.');}const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function palette(){const q=$('paletteInput').value.toLowerCase();$('paletteResults').innerHTML=pages.filter(p=>p[1].toLowerCase().includes(q)).map(p=>link(p[1],'/#'+p[0],'')).join('')+clients().filter(c=>[c.name,c.channel_title].join(' ').toLowerCase().includes(q)).slice(0,20).map(c=>link(c.channel_title||c.name,'/channels/'+c.id,'',true)).join('');}
function paletteOpen(){if(!$('palette').open)$('palette').showModal();$('paletteInput').focus();palette();}
async function handleAction(actionName,id,element){
 if(actionName==='cloud-now'){await action('/api/cloud/action',{id,action:'post_now',confirmed:true},r=>toast(r.notice||'Checking Drive for one new Public video.'));return;}

 if(['add-github','reassign','health','failover-preview'].includes(actionName))throw Error('This workspace runs on Azure.');
 if(actionName==='delete-channel'||actionName==='delete-selected'){const ids=actionName==='delete-selected'?[...selected]:[id];if(!ids.length)throw Error('Select at least one channel.');modal('Delete '+ids.length+' channel(s)?','<p>Saved authorization, folder routes, video records and stats for these channels will be removed from this workspace.</p><p>YouTube videos and Drive files stay. An encrypted recovery copy is kept. Fresh history will not identify older uploads.</p><form id="cleanupForm"><input type="hidden" name="ids" value="'+esc(JSON.stringify(ids))+'">'+input('phrase','Type DELETE to confirm','','text','required pattern="DELETE" autocomplete="off"')+'<button class="danger">Delete selected channels</button></form>');return;}
 if(actionName==='reset-workspace'){modal('Reset all channel data?','<p>Remove all channels, saved platform connections, folder assignments, stats and video records. Your sign-in account and Google API app settings stay. No provider videos/files will be deleted.</p><form id="cleanupForm"><input type="hidden" name="reset" value="yes">'+input('phrase','Type RESET to confirm','','text','required pattern="RESET" autocomplete="off"')+'<button class="danger">Reset workspace</button></form>');return;}

 if(actionName==='cloud-stage'){const row=S.cloud.matching[Number(id)];cloudRouteDialog(row);return;}
 if(actionName==='cloud-review'){document.getElementById('cloud-route-'+id)?.scrollIntoView({block:'center',behavior:'smooth'});return;}
 if(actionName==='cloud-custom'){cloudRouteDialog(null);return;}
 if(actionName==='drive-refresh'){const form=$('cloudRouteForm'),row=form?fieldData(form):null;await action('/api/drive/discover',{},()=>{if(row)cloudRouteDialog(row);else toast('Drive folders refreshed.');});return;}
 if(actionName==='channel-folder'){cloudRouteDialog({youtube_connection:id});return;}
 if(actionName==='cloud-handover'){await action('/api/cloud/migration/preview',{id},r=>{modalData={id};if(!r.ready){modal('Setup needs review','<p>Wait for the read-only check to finish and verify the exact source and channel.</p>');return;}confirmDialog('Confirm this channel setup','<p>Channel ID: '+esc(r.channel_id)+'<br>Folder ID: '+esc(r.folder_id)+'</p><p>'+esc(r.notice)+'</p><p>Confirm that no other tool is uploading this folder to the same channel. '+(S.cloud?.auto_start_confirmed&&S.cloud?.live_uploads?'Public posting will start within the daily limit after this confirmation.':'The route stays paused until you start it.')+'</p>','cloud-handover');});return;}
 if(actionName==='cloud-start'||actionName==='cloud-private'){modalData={id,action:actionName==='cloud-start'?'enable':'private_test'};const r=S.cloud.routes.find(r=>r.id===id);confirmDialog(actionName==='cloud-start'?'Start Public publishing':'Run one approved private test','<p>'+esc(r.config.folder_path)+' → '+esc(r.config.name)+'<br>'+esc(r.channel_id)+'</p><p>This may upload eligible videos. Reserved or uncertain videos are never retried.</p>','cloud-start');return;}
 if(actionName==='cloud-dry'||actionName==='cloud-pause'){await action('/api/cloud/action',{id,action:actionName==='cloud-dry'?'dry_run':'pause'});return;}
 if(actionName==='server-backup'||actionName==='server-worker'){await action('/api/cloud/server',{action:actionName==='server-backup'?'backup':'restart-worker'});return;}
 if(actionName==='sessions'){const r=await api('/auth/sessions');modal('Active sessions',r.sessions.map(s=>'<p>Expires '+esc(stamp(s.expires*1000))+'</p>').join('')+button('Sign out everywhere','logout-all'));return;}
 if(actionName==='logout-all'){await api('/auth/logout-all',{});location.href='/login';return;}
 if(actionName==='totp-setup'){const r=await api('/auth/totp/setup',{});modal('Set up authenticator','<p>Add this key to your authenticator app. Keep it private.</p><code>'+esc(r.secret)+'</code><form id="totpForm">'+input('otp','6-digit code','','text','required pattern="[0-9]{6}" autocomplete="one-time-code"')+'<button class="primary">Enable and sign out</button></form>');return;}
 if(actionName==='close-modal'){$('modal').close();return;}
 if(actionName==='copy-auth'){if(!S.job.auth_url)throw Error('No pending authorization link.');await navigator.clipboard.writeText(S.job.auth_url);toast('Authorization link copied. Open it in your intended browser profile.');return;}
 if(actionName==='private-auth'){await api('/api/auth/open',{});return;}
 if(actionName==='google-emails'){await action('/api/google/emails',{},result=>toast((result.updated||0)+' Google emails verified. Connections without email permission need Reconnect once.'));return;}
 if(actionName==='avatars'){await action('/api/avatars/refresh',{});return;}
 if(actionName==='sync'){await action('/api/sync');return;}
 if(actionName==='connect-youtube'||actionName==='connect-drive'){googleDialog(actionName==='connect-drive'?'drive':'youtube',id);return;}
 if(actionName==='route-youtube'){cloudRouteDialog({youtube_connection:id});return;}
 if(actionName==='route-youtube'){await action('/api/draft',{youtube_connection:id,name:S.connections[id].label,source_type:'drive'},()=>{location.href='/#wizard';});return;}
 if(actionName==='folder-previous'){folderPage=Math.max(0,folderPage-1);render();return;}
 if(actionName==='folder-next'){folderPage++;render();return;}
 if(actionName==='folder-route'){cloudRouteDialog({folder_id:id});return;}if(actionName==='legacy-folder-route-disabled'){const f=S.drive_root.folders.find(f=>f.id===id);await action('/api/draft',{source_type:'drive',folder_id:f.id,name:f.name,drive_connection:S.drive_root.connection_id},()=>{location.href='/#wizard';});return;}
 if(actionName==='edit'){location.href='/#matching';return;}if(actionName==='legacy-edit-disabled'){await action('/api/draft',S.clients[id],()=>{location.href='/#wizard';if(current==='wizard')render();});return;}
 if(actionName==='open-channel'){reviewChannel(id);return;}
 if(actionName==='client-action'){const split=id.lastIndexOf(':'),cid=id.slice(0,split),operation=id.slice(split+1),c=S.clients[cid];if(operation==='scan'){await action('/api/channel/source',{id:cid});return;}modalData={id:cid,action:operation,confirmed:true};confirmDialog(operation==='enable'?'Start Public publishing':operation==='deploy'?'Prepare private worker':operation==='pause'?'Pause future checks':'Read-only dry run',route(c)+'<p>'+esc({enable:'New eligible videos may be uploaded as Public on future worker checks. Daily limits and existing reservations remain in force.',deploy:'This creates or updates the private GitHub worker. It stays paused. Existing upload history is retained. New worker source includes Telegram support if configured.',pause:'Future scheduled publishing is paused. A worker already running may finish.',dry_run:'Checks the source without uploading or moving source files.'}[operation]||'Review this action.')+'</p>','client-action');return;}
 if(actionName==='filter-status'){filters.status=id;page=0;render();return;}
 if(actionName==='clear-filters'){filters={search:'',status:'',github:'',source:'',tag:''};page=0;render();return;}
 if(actionName==='save-view'){modal('Save this channel view','<form id="saveViewForm">'+input('name','View name','','text','required maxlength="80"')+'<button class="primary">Save view</button></form>');return;}
 if(actionName==='previous-channels'){page=Math.max(0,page-1);render();return;}if(actionName==='next-channels'){page++;render();return;}
 if(actionName==='previous-videos'){videoPage=Math.max(0,videoPage-1);render();return;}if(actionName==='next-videos'){videoPage++;render();return;}
 if(actionName==='clear-recent'){recentFilters={search:'',client:'',mode:'all'};recentPage=0;render();return;}
 if(actionName==='previous-recent'||actionName==='next-recent'){recentPage=Math.max(0,recentPage+(actionName==='next-recent'?1:-1));render();return;}
 if(actionName==='clear-videos'){videoFilters={search:'',status:'',client:''};recordDay='';videoPage=0;render();return;}
 if(actionName==='bar-videos'){recordDay=id;location.href='/#videos';return;}
 if(actionName==='failover-preview'){await action('/api/failover/preview',{},result=>modal('Failover readiness · no moves performed',resultTable(result)+(result.rows?.length?'':'<p>No checked account currently meets a failover trigger.</p>')));return;}
 if(actionName==='telegram-link'){await action('/api/telegram/link',{});return;}if(actionName==='telegram-test'){await action('/api/telegram/test',{});return;}
 if(actionName==='download-csv'){await download('/api/export/uploads','DriveCast-videos.csv');return;}if(actionName==='activity-csv'){await download('/api/export/activity','DriveCast-activity.csv');return;}
 if(actionName==='export-backup'){await download('/api/backup','DriveCast-'+new Date().toISOString().slice(0,10)+'.drivecast');return;}
 if(actionName==='remote-fetch'){modalData={connection:$('remoteForm').elements.connection_id.value,repo:$('remoteForm').elements.repo_name.value};confirmDialog('Fetch saved GitHub workspace','<p>This retrieves private recovery data. Review your current backup before replacing local workspace data.</p>','remote-fetch');return;}
 if(actionName==='save-draft'){await action('/api/draft',routeFormData());toast('Draft saved.');return;}
 if(actionName==='validate-route-source'){const d=routeFormData();await action('/api/source/validate',d,result=>{toast('Source validated: '+count(result.source_stats?.available)+' readable videos.');render();updateRoutePreview();});return;}
 if(actionName==='fix-connection'){const c=S.connections[id];location.href='/#'+({youtube:'youtube',drive:'drive',github:'github'}[c.kind]||'automation');if(c.kind==='youtube'||c.kind==='drive')googleDialog(c.kind,c.id);else if(c.kind==='github')githubDialog(c.id);return;}
 if(actionName==='fix-all'){const list=Object.values(S.connections).filter(c=>c.status!=='Connected'||(c.expires_at||c.user_login_expires_at)&&Date.parse(c.expires_at||c.user_login_expires_at)<Date.now()+7*86400000);modal('Connection recovery walkthrough',list.length?list.map((c,i)=>'<div class="item">'+pic(c)+'<div class="grow"><strong>'+(i+1)+'. '+esc(c.label)+'</strong><small>'+esc(reason(c))+'</small></div>'+button('Open connection section','fix-connection',c.id)+'</div>').join(''):'<p>No known failed or expiring connections. Sync first if the saved checks are old.</p>');return;}
 if(actionName==='confirm'){const body=modalData;if(id==='cloud-start'){$('modal').close();await action('/api/cloud/action',{...body,confirmed:true});return;}if(id==='cloud-handover'){$('modal').close();await action('/api/cloud/migration/confirm',{...body,confirmed:true,other_runners_stopped:true});return;}$('modal').close();if(id==='client-action'){await action('/api/client/action',body);return;}if(id==='route-save'){await action('/api/client',body,result=>{toast('Route saved. Prepare it before starting Public publishing.');location.href='/channels/'+(result.id||body.id);});return;}if(id==='bulk'){await action('/api/bulk',{...body,confirmed:true},result=>{selected.clear();modal('Bulk results',resultTable(result));});return;}if(id==='csv'){await action('/api/csv/import',{...body,confirmed:true},result=>modal('CSV import results',resultTable(result)));return;}if(id==='schedule'){await action('/api/schedule',body);return;}if(id==='reassign'){await action('/api/migration',body,result=>toast((result.migrated||0)+' channel reassigned with verified upload history.'));return;}if(id==='automation'){await action('/api/automation',{...body,confirmed:true});return;}if(id==='backup-import'){await api('/api/import/restore',{ticket:body.ticket,confirmed:true});await refresh(true);toast('Backup restored locally. Remote workers were not enabled.');return;}if(id==='remote-fetch'){await action('/api/remote/fetch',body);return;}}
}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b)return;event.preventDefault();try{await handleAction(b.dataset.action,b.dataset.id||'',b);}catch(error){toast(error.message,true);}});
document.addEventListener('submit',async event=>{const form=event.target;const formId=form.getAttribute('id');if(!formId&&!form.classList.contains('poolSettings'))return;event.preventDefault();const submit=form.querySelector('button[type=submit],button:not([type])');if(submit)submit.disabled=true;try{const d=fieldData(form);
 if(formId==='cloudSettingsForm'){await action('/api/cloud/settings',{auto_start_confirmed:d.auto_start_confirmed});toast('New channel posting preference saved.');return;}
 if(formId==='cleanupForm'){const reset=d.reset==='yes';if(d.phrase!==(reset?'RESET':'DELETE'))throw Error('Enter the confirmation word.');await action('/api/workspace/cleanup',{confirmed:true,reset,phrase:d.phrase,ids:reset?[]:JSON.parse(d.ids)},()=>{selected.clear();$('modal').close();history.replaceState(null,'','/#channels');navigate();toast(reset?'Fresh workspace ready. Connect Drive and YouTube.':'Channel data deleted. Provider videos/files kept.');});return;}
 if(formId==='cloudRouteForm'){d.channel_id=S.connections[d.youtube_connection]?.channel_id;d.confirmed=true;await action('/api/cloud/stage',d,result=>{location.hash='matching';navigate();document.getElementById('cloud-route-'+result.id)?.scrollIntoView({block:'center'});toast('Read-only check queued. Confirm channel setup below after it finishes.');});$('modal').close();return;}
 if(formId==='totpForm'){await api('/auth/totp/enable',d);location.href='/login';return;}
 if(formId==='unlockForm'){await api('/api/unlock',d);form.elements.password.value='';await refresh(true);return;}
 if(formId==='googleAppForm'){const file=form.elements.oauth_file.files[0];if(file)d.oauth=JSON.parse(await file.text());delete d.oauth_file;await action('/api/settings/google',d);form.reset();return;}
 if(formId==='googleConnectForm'){d.require_exact_name=d.kind==='youtube';if(d.id)d.expected_channel_id=S.connections[d.id]?.channel_id;form.dataset.authPending='true';formFeedback(form,'Creating your Google sign-in link…');await action('/api/google',d);return;}
 if(formId==='driveRootForm'){await action('/api/drive/root',{...d,confirmed:true});return;}
 if(formId==='telegramBotForm'){await action('/api/telegram/connect',d);form.reset();return;}
 if(formId==='telegramSettingsForm'){await action('/api/telegram/settings',d);return;}
 if(formId==='automationForm'){modalData=d;confirmDialog('Review background automation','<p>'+(d.armed?'Activate automatic pauses, safe failover attempts, configured Telegram commands and reports while this server runs.':'Save these rules with background changes inactive.')+'</p><p>Uncertain uploads will remain quarantined. Live worker migrations may occur only after activation and successful safety checks.</p>','automation');return;}
 if(formId==='reassignForm'){modalData={ids:[d.channel_id],target:d.target,confirmed:true};await action('/api/migration/preview',modalData,result=>{if(!result.ready){modal('Reassignment blocked',resultTable(result)+'<p>Existing routes and records are unchanged.</p>');return;}confirmDialog('Reassign this channel',resultTable(result)+'<p>Stop the original worker, verify all branches and upload history, then resume on the chosen GitHub account. Maximum 2 channels per account.</p>','reassign');});return;}
 if(formId==='saveViewForm'){$('modal').close();await action('/api/views',{...filters,name:d.name});return;}
 if(formId==='bulkForm'){modalData={...modalData,...d};await action('/api/bulk/preview',modalData,result=>confirmDialog('Bulk preview',resultTable(result)+'<p>Only ready channels will run. Every channel gets its own result.</p>','bulk'));return;}
 if(formId==='csvForm'){modalData={csv:await form.elements.file.files[0].text()};await action('/api/csv/preview',modalData,result=>confirmDialog('CSV validation preview',resultTable(result)+'<p>Only valid rows are imported. This does not start any worker.</p>','csv'));return;}
 if(formId==='scheduleForm'){modalData={...d,ids:[form.dataset.client]};confirmDialog('Apply publication preferences','<p>This updates the deployed worker schedule after verifying no run is active, retains all reservations, and restores its previous enabled state.</p><p>Mode: '+esc(d.schedule_mode==='interval'?'Immediately as Public':'Preferred windows')+' · '+esc(d.schedule_timezone)+' · '+esc(d.schedule_windows)+'</p>','schedule');return;}
 if(formId==='routeForm'){modalData={...routeFormData(),confirmed:true};const yt=S.connections[modalData.youtube_connection],folder=S.drive_root?.folders?.find(x=>x.id===modalData.folder_id);confirmDialog('Confirm folder → YouTube channel','<p><strong>'+esc(folder?.path||'No folder selected')+' → '+esc(yt?.label||'No channel selected')+'</strong></p><p>YouTube ID: '+esc(yt?.channel_id||'Missing')+'<br>Google sign-in: '+esc(yt?.google_email||'Email not shared yet')+'</p><p>Only this folder feeds this channel. '+(modalData.id?'This updates the existing channel route and preserves its worker and upload history.':'Prepare and Start are separate actions.')+'</p>','route-save');return;}
 if(formId==='backupPreviewForm'){const file=form.elements.backup.files[0];if(file.size>48*1024*1024)throw Error('Backup too large.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const result=await api('/api/import/preview',{file:btoa(binary),password:d.password});form.elements.password.value='';modalData={ticket:result.ticket};confirmDialog('Review backup import','<p>'+result.clients+' channels · '+result.connections+' connections · '+result.records+' video records.</p><p>Exported '+esc(result.exported_at)+'. Current local data is backed up before restore. Remote workers are unchanged.</p>','backup-import');return;}
 if(formId==='remoteForm'){await action('/api/remote/save',{connection:d.connection_id,repo:d.repo_name});return;}
 }catch(error){delete form.dataset.authPending;formFeedback(form,error.message,true);toast(error.message,true);}finally{if(submit)submit.disabled=form.dataset.authPending==='true';}});
document.addEventListener('change',async event=>{const el=event.target;try{
 if(el.dataset.select){el.checked?selected.add(el.dataset.select):selected.delete(el.dataset.select);$('selectedCount').textContent=selected.size+' selected';return;}
 if(el.id==='selectPage'){document.querySelectorAll('[data-select]').forEach(e=>{e.checked=el.checked;el.checked?selected.add(e.dataset.select):selected.delete(e.dataset.select);});$('selectedCount').textContent=selected.size+' selected';return;}
 const filterMap={fleetStatus:'status',fleetGithub:'github',fleetSource:'source',fleetTag:'tag'};if(filterMap[el.id]){filters[filterMap[el.id]]=el.value;page=0;render();return;}
 if(el.id==='savedView'&&el.value){filters={...filters,...S.saved_views[el.value]};page=0;render();return;}
 if(el.id==='recentClient'||el.id==='recentMode'){recentFilters[el.id==='recentClient'?'client':'mode']=el.value;recentPage=0;render();return;}
 if(el.id==='videoClient'||el.id==='videoStatus'){videoFilters[el.id==='videoClient'?'client':'status']=el.value;videoPage=0;render();return;}
 if(el.id==='chartPeriod'){chartPeriod=Number(el.value);render();return;}
 if(el.closest('#routeForm')&&el.name==='youtube_connection'&&!$('routeForm').elements.name.value)$('routeForm').elements.name.value=S.connections[el.value]?.label||'';
 if(el.id==='duplicateSettings'&&el.value){const c=S.clients[el.value],f=$('routeForm');for(const key of ['schedule_mode','schedule_timezone','schedule_windows','max_uploads_per_day','check_minutes'])if(f.elements[key])f.elements[key].value=c[key]??'';f.elements.tags.value=(c.tags||[]).join(', ');toast('Publishing settings copied. Source and YouTube destination stay as you selected.');}
 if(el.closest('#routeForm'))updateRoutePreview();
 }catch(error){toast(error.message,true);}});
let folderSearch='',folderPage=0;
let searchTimer;document.addEventListener('input',event=>{const el=event.target;if(['fleetSearch','videoSearch','folderSearch','recentSearch'].includes(el.id)){clearTimeout(searchTimer);const start=el.selectionStart;searchTimer=setTimeout(()=>{if(el.id==='fleetSearch'){filters.search=el.value;page=0;}else if(el.id==='recentSearch'){recentFilters.search=el.value;recentPage=0;}else if(el.id==='folderSearch'){folderSearch=el.value;folderPage=0;}else{videoFilters.search=el.value;videoPage=0;}render();const next=$(el.id);next.focus();next.setSelectionRange(start,start);},180);}if(el.closest('#routeForm'))updateRoutePreview();});
$('closeModal').onclick=()=>$('modal').close();$('closePalette').onclick=()=>$('palette').close();$('commandButton').onclick=paletteOpen;$('paletteInput').oninput=palette;$('paletteResults').onclick=()=>$('palette').close();$('menuButton').onclick=()=>{const open=$('sidebar').classList.toggle('open');$('menuButton').setAttribute('aria-expanded',String(open));};
document.addEventListener('keydown',event=>{if(event.key==='Escape'){if($('palette').open){event.preventDefault();$('palette').close();}else if($('modal').open){event.preventDefault();$('modal').close();}}if(event.key==='Enter'&&$('palette').open&&event.target===$('paletteInput')){event.preventDefault();$('paletteResults').querySelector('a')?.click();}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();paletteOpen();}});window.addEventListener('hashchange',navigate);
$('signOut').onclick=async()=>{try{await api('/auth/logout',{});location.replace('/login');}catch(error){toast(error.message,true);}};
(async()=>{try{await refresh(true);navigate();try{const response=await fetch('/auth/session');if(response.ok){const auth=await response.json();$('signOut').classList.toggle('hidden',!auth.signed_in);}}catch{}setInterval(()=>refresh().catch(()=>{}),5000);setInterval(countdowns,1000);}catch(error){toast(error.message,true);}})();

function unassignedDetail(yt){$('heading').textContent=yt.label;return '<article class="card"><div class="row">'+pic(yt,'large')+'<div><h2>'+esc(yt.label)+'</h2><small>Verified YouTube ID: '+esc(yt.channel_id)+'</small>'+googleEmail(yt)+'</div></div><p>'+chip(yt.status,yt.status==='Connected'?'':'warn')+'</p><p class="muted">This channel is authorized. Choose a Drive folder to finish setup. Authorizing this channel does not start publishing.</p>'+button('Connect Drive folder','route-youtube',yt.id,'primary')+button('Delete channel','delete-channel',yt.id,'danger')+'</article><div class="kpis">'+[['Subscribers',yt.stats?.hiddenSubscriberCount===true||yt.stats?.hiddenSubscriberCount==='true'?null:yt.stats?.subscriberCount],['Lifetime views',yt.stats?.viewCount],['Channel videos',yt.stats?.videoCount],['Views · 30 days',yt.analytics?.views_30d]].map(([label,value])=>'<article class="card kpi"><span>'+label+'</span><strong>'+count(value)+'</strong><small>Checked: '+stamp(label.includes('30')?yt.analytics?.checked_at:yt.checked_at)+'</small></article>').join('')+'</div>'+empty('No route history yet','Choose a Drive subfolder and daily limit for this exact YouTube channel.');}

function matching(){const rows=S.cloud?.matching||[],routes=S.cloud?.routes||[];return '<div class="notice"><strong>Match → test → confirm</strong><p>A unique folder name matches a channel title after trimming spaces and ignoring letter case. Folders refresh automatically every 5 minutes and after YouTube authorization. Choose a folder, run a dry test, then confirm channel setup. Duplicate names need your exact folder/channel choice.</p></div><article class="card"><div class="section-head"><div><h2>Drive folders and authorized channels</h2><small>Last folder scan: '+stamp(S.drive_root?.checked_at)+' · Auto-refresh every 5 minutes</small></div><div class="actions">'+button('Refresh Drive folders','drive-refresh')+button('Choose exact folder and channel','cloud-custom')+'</div>'+'</div>'+(rows.length?rows.map((r,i)=>'<div class="item"><div class="grow"><strong>'+esc(r.name)+'</strong><small>'+esc(r.folders.map(f=>f.path).join(' · ')||'No folder')+'</small><small>'+esc(r.channels.map(c=>c.channel_id).join(' · ')||'No authorized destination')+'</small></div>'+chip(r.status,r.ready?'':'warn')+((routes.find(x=>x.channel_id===r.channel_id))?(r.existing_client_id?link('Open channel','/channels/'+r.existing_client_id,'button',true):button('Review setup','cloud-review',routes.find(x=>x.channel_id===r.channel_id).id)):r.ready?button('Review cloud preview','cloud-stage',String(i)):r.authorization_action?button('Authorize YouTube channel','connect-youtube'):r.status==='Ambiguous name'?button('Choose exact IDs','cloud-custom'):r.channels.length?button('Connect Drive folder','channel-folder',r.youtube_connection||r.channels[0].id):'')+'</div>').join(''):empty('Connect Drive and YouTube first','Folder matching uses saved authorized channels only.',link('Open Google Drive','/#drive','button')) )+'</article><article class="card"><h2>Cloud route previews</h2>'+(routes.length?routes.map(r=>'<div class="item wrap" id="cloud-route-'+esc(r.id)+'"><div class="grow"><strong>'+esc(r.config.name)+'</strong><small>'+esc(r.config.folder_path)+' → '+esc(r.channel_id)+'</small><small>'+esc(r.dry_run?.notice||'Waiting for a cloud worker')+' · '+esc(stamp(r.dry_run?.checked_at))+'</small><small>'+count(r.dry_run?.eligible)+' eligible videos · '+r.config.max_uploads_per_day+' attempts/day</small></div>'+chip(r.enabled?'Running':'Paused preview',r.enabled?'':'neutral')+button('Read-only dry run','cloud-dry',r.id)+(r.dry_run?.checked_at&&!r.history_verified?button('Confirm channel setup','cloud-handover',r.id):'')+(r.history_verified&&S.cloud.live_uploads&&!r.enabled?button('Private test','cloud-private',r.id)+button('Start Public','cloud-start',r.id):'')+(r.enabled?button('Pause','cloud-pause',r.id):'')+forceNowButton({...r.config,cloud_route_id:r.id})+button('Delete preview','delete-channel',r.id,'danger')+'</div>').join(''):empty('No cloud routes staged','Review a matching pair above. Existing channels are not moved.'))+'</article>';}
function cloudRouteDialog(row){
 const root=S.drive_root,folders=root?.folders||[],yt=conns('youtube');
 if(!root?.folder_id){modal('Connect Google Drive first','<p>Connect one project main folder before choosing a channel subfolder.</p>'+link('Open Google Drive','/#drive','button primary'));return;}
 if(!yt.length){modal('Authorize YouTube first','<p>Your Drive folders stay saved. Authorize the intended YouTube channel next.</p>'+button('Authorize YouTube channel','connect-youtube','','primary'));return;}
 modal('Review exact cloud route','<p>This saves a paused cloud preview and queues a read-only dry run. No upload starts until you approve the exact route.</p><p class="help">Last folder scan: '+stamp(root.checked_at)+'. New folder missing? Refresh the list below. The folder must be inside your connected main folder.</p>'+(root.notice?'<p class="notice warn">'+esc(root.notice)+'</p>':'')+'<form id="cloudRouteForm">'+select('folder_id','Drive subfolder',folders.map(f=>({id:f.id,label:f.path||f.name})),row?.folder_id||'','Choose a Drive subfolder').replace('<select ','<select required ')+select('youtube_connection','Verified YouTube destination',yt.map(c=>({...c,label:c.label+' · '+c.channel_id})),row?.youtube_connection||'','Choose the exact YouTube channel').replace('<select ','<select required ')+input('max_uploads_per_day','Daily upload attempt limit',row?.max_uploads_per_day||2,'number','required min="1" max="20"')+'<p class="help">Public posting starts only after confirmed setup and within your daily limit.</p><button class="primary"'+(!folders.length?' disabled':'')+'>Confirm preview · no uploads</button></form><div class="actions">'+button('Refresh Drive folders','drive-refresh')+link('Check main folder','/#drive','button')+'</div>'+(!folders.length?'<p class="notice warn">No subfolders are visible yet. Create a channel subfolder inside the main folder, then refresh. The connected Drive account needs access to it.</p>':''));
}
function recoveryCard(){const b=S.cloud?.last_backup||{},targets=b.targets||{};return '<article class="card"><div class="section-head"><div><h2>Server recovery outside Azure</h2><p class="help">Encrypted checkpoints preserve logins, authorizations, records and bundled source.</p></div>'+chip(b.off_azure_verified?'Private Drive verified':'Independent backup not verified',b.off_azure_verified?'':'warn')+'</div><p>'+esc(b.notice||'No verified server checkpoint yet.')+'</p><small>Checkpoint created: '+stamp(b.at)+'</small><div class="actions">'+chip('Google Drive: '+(targets.drive?.verified?'Verified':'Not verified'),targets.drive?.verified?'':'neutral')+chip('Azure Blob: '+(targets.azure?.verified?'Verified':'Not verified'),targets.azure?.verified?'':'neutral')+button('Run encrypted server backup','server-backup')+'</div><p class="help">Important changes queue a background checkpoint; an hourly backup runs too. Keep the original recovery key separately. Recovery resumes from the last verified checkpoint, with routes paused.</p></article>';}
function serverPage(){const c=S.cloud||{},jobs=c.jobs||[],healthy=Object.entries(c.services||{});return '<div class="notice '+(c.live_uploads?'':'warn')+'"><strong>'+esc(c.hosted?'Azure hosted workspace':'Local preparation workspace')+' · '+esc(c.version)+'</strong><p>'+esc(c.live_uploads?'Live publishing is permitted only for individually confirmed cloud routes.':'Dry-run-only mode. No live uploads or existing channel migrations are enabled.')+'</p></div><div class="kpis">'+[['Free disk',Math.round((c.disk_free||0)/1024**3)+' GB'],['Worker capacity',c.worker_capacity||2],['Durable reservations',c.reservations||0],['Uncertain / reserved',c.uncertain||0]].map(([a,b])=>'<article class="card kpi"><span>'+a+'</span><strong>'+esc(b)+'</strong></article>').join('')+'</div><div class="grid cols2"><article class="card"><h2>Service heartbeat</h2>'+healthy.map(([name,last])=>'<div class="item"><strong>'+esc(name)+'</strong><div class="grow"></div>'+chip(last&&Date.now()/1000-last<120?'Online':'Not seen',last&&Date.now()/1000-last<120?'':'warn')+'<small>'+esc(last?ago(last*1000):'Not started')+'</small></div>').join('')+'<p>Workers recover safe queued work. A reserved upload is quarantined after a lost heartbeat.</p>'+button('Restart idle worker service','server-worker')+'</article><article class="card"><h2>Recovery</h2><p>Last backup: '+esc(stamp(c.last_backup?.at))+'</p><p>'+esc(c.last_backup?.notice||'No verified cloud backup yet')+'</p><p>'+esc(c.trial_ends?'Trial ends: '+c.trial_ends+'. Export and choose continuation before then.':'Paid hosting: no trial expiry is configured.')+'</p><div class="actions">'+button('Run encrypted backup','server-backup')+button('Export workspace','export-backup')+'</div><p class="help">A restored server starts paused. Verify the previous server is stopped before resuming.</p></article></div><article class="card"><h2>Recent worker checks</h2>'+jobs.slice(0,30).map(j=>'<div class="item"><div class="grow"><strong>'+esc(j.route_id)+'</strong><small>'+esc(j.notice)+'</small></div>'+chip(j.mode+' · '+j.state,j.state==='attention'||j.state==='quarantined'?'warn':'neutral')+'</div>').join('')+'</article>'+(c.hosted?'<article class="card"><h2>Sign-in security</h2><div class="actions">'+button('Active sessions','sessions')+button('Set up authenticator','totp-setup')+button('Sign out everywhere','logout-all')+'</div><p class="help">Registration is invite-only by default. Each login owns a separate workspace.</p></article>':'');}

function cloudAutomation(){return '<article class="card"><h2>New channel posting</h2><form id="cloudSettingsForm"><label class="check"><input type="checkbox" name="auto_start_confirmed"'+(S.cloud?.auto_start_confirmed?' checked':'')+'> Start Public posting after I confirm an exact folder/channel setup</label><p class="help">Authorization alone never starts uploads. A matched folder, successful dry check and exact channel confirmation are still required. The server publishing gate must also be on.</p><button>Save posting preference</button></form></article><article class="card"><h2>Azure worker protection</h2><p>Each check can publish one new video. Automatic checks are five minutes apart, within your per-channel daily limit. Post force now queues one immediate check and keeps the same limits.</p><p>Worker heartbeats and database leases prevent double claims. Reserved or uncertain uploads are retained and never blindly repeated.</p><p>Default project cap: 90 attempts/day. Actual Google API quota still applies.</p><div class="actions">'+link('Worker health','/#server','button')+link('Folder matching','/#matching','button')+'</div></article>'; }
